def receive_data(self, s):
    save_path = prefs.get_save_path()

    path = os.path.join(save_path, s.relative_path)
    if path != self.current_path:
        self.close_current_file()
        self.current_path = path
        self.current_mode = s.file_mode
        self.current_type = s.file_type
        self.current_mtime = s.time.mtime
        self.current_mtime_usec = s.time.mtime_usec

    if not self.current_gfile:
        self.current_gfile = Gio.File.new_for_path(path)
        # Check for valid path (GFile resolves paths upon creation).
        if self.save_path_file.get_relative_path(self.current_gfile) is None:
            raise Exception(_("Resolved path is not valid: %s -> %s") % (path, self.current_gfile.get_path()))

    if s.file_type == FileType.DIRECTORY:
        os.makedirs(path, exist_ok=True)
    elif s.file_type == FileType.SYMBOLIC_LINK:
        make_symbolic_link(self.op, path, s.symlink_target)
    else:
        if self.current_stream == None:
            self.current_stream = self.current_gfile.create(Gio.FileCreateFlags.NONE, None)

        if not s.chunk:
            return

        self.current_stream.write_bytes(GLib.Bytes(s.chunk), None)
        self.op.progress_tracker.update_progress(len(s.chunk))

def prepare_authors_on_upload(title, authr):
    if title != _(u'Unknown') and authr != _(u'Unknown'):
        entry = calibre_db.check_exists_book(authr, title)
        if entry:
            log.info("Uploaded book probably exists in library")
            flash(_(u"Uploaded book probably exists in the library, consider to change before upload new: ")
                  + Markup(render_title_template('book_exists_flash.html', entry=entry)), category="warning")

    input_authors, renamed = prepare_authors(authr)

    sort_authors_list = list()
    db_author = None
    for inp in input_authors:
        stored_author = calibre_db.session.query(db.Authors).filter(db.Authors.name == inp).first()
        if not stored_author:
            if not db_author:
                db_author = db.Authors(inp, helper.get_sorted_author(inp), "")
                calibre_db.session.add(db_author)
                calibre_db.session.commit()
            sort_author = helper.get_sorted_author(inp)
        else:
            if not db_author:
                db_author = stored_author
            sort_author = stored_author.sort
        sort_authors_list.append(sort_author)
    sort_authors = ' & '.join(sort_authors_list)
    return sort_authors, input_authors, db_author, renamed

def do_PUT(self) -> None:
    """This method handles the PUT requests to add agents to the Registrar Server.

    Currently, only agents resources are available for PUTing, i.e. /agents. All other PUT uri's
    will return errors.
    """
    session = SessionManager().make_session(engine)

    _, agent_id = self._validate_input("PUT", True)
    if not agent_id:
        return

    try:
        content_length = int(self.headers.get("Content-Length", 0))
        if content_length == 0:
            web_util.echo_json_response(self, 400, "Expected non zero content length")
            logger.warning("PUT for %s returning 400 response. Expected non zero content length.", agent_id)
            return

        post_body = self.rfile.read(content_length)
        json_body = json.loads(post_body)

        auth_tag = json_body["auth_tag"]
        try:
            agent = session.query(RegistrarMain).filter_by(agent_id=agent_id).first()
        except NoResultFound as e:
            raise Exception("attempting to activate agent before requesting " f"registrar for {agent_id}") from e
        except SQLAlchemyError as e:
            logger.error("SQLAlchemy Error: %s", e)
            raise

        assert agent
        assert isinstance(agent.key, str)
        ex_mac = crypto.do_hmac(agent.key.encode(), agent_id)
        if ex_mac == auth_tag:
            try:
                session.query(RegistrarMain).filter(RegistrarMain.agent_id == agent_id).update(
                    {"active": int(True)}
                )
                session.commit()
            except SQLAlchemyError as e:
                logger.error("SQLAlchemy Error: %s", e)
                raise
        else:
            raise Exception(f"Auth tag {auth_tag} does not match expected value {ex_mac}")

        web_util.echo_json_response(self, 200, "Success")
        logger.info("PUT activated: %s", agent_id)
    except Exception as e:
        web_util.echo_json_response(self, 400, f"Error: {str(e)}")
        logg

